// in-memory DB

// path마다 PK를 뭐로 쓸지
const META = {
  "/order/orderlist": { key: "orderNo" },
  "/order/completed": { key: "orderNo" },
  "/buyer/partorder": { key: "poNo" },
  "/buyer/buyercustomer": { key: "buyerNo" },
  "/order/sellercustomer": { key: "cusNo" },
  "/plan/planlist": { key: "planNo" },
  "/plan/bomlist": { key: "bomId" },
  "/plan/itemlist": { key: "itemNo" },
  "/stock/item": { key: "itemNo" },
  "/stock/partstocks": { key: "stockNo" },
};

const MOCK_DB = {
  // 판매거래처
  "/order/sellercustomer": [
    {
      cusNo: 1,
      cusComp: "판매처 A",
      cusName: "홍길동",
      cusEmail: "a@test.com",
      cusPhone: "010-1111-2222",
      cusAddr: "서울 강남구"
    }
  ],
  // 상품주문서
  "/order/orderlist": [
    {
      orderNo: 1,
      orderDate: "2025-10-02",
      cusComp: "판매처 A",
      itemName: "완제품 A",
      orderQty: 19,
      orderPrice: 300000,
      orderState: "승인대기",
      orderDeliState: "납품대기",
      deliveryDate: "2025-10-24",
      cusAddr: "주소",
      totalPrice: 5700000
    },
  ],

  // 주문완료현황
  "/order/completed": [
    // 납품완료된 것들이 여기로 이동
  ],

  // 구매거래처
  "/buyer/buyercustomer": [
    {
      buyerNo: 1,
      buyerComp: "구매처 A",
      buyerName: "강감찬",
      buyerEmail: "a@buyer.com",
      buyerPhone: "010-5555-1111",
      buyerAddr: "대전 유성구"
    }
  ],

  // 부품
  "/buyer/partlist": [
    {
      partNo: 1,            // 일련번호 / PK
      partName: "부품 A",    // 부품명
      buyerComp: "구매처 A", // 구매처명
      partCode: "01",       // 부품코드
      partSpec: "2*3*4",    // 부품규격
      partPrice: 20000      // 부품단가
    },
  ],

  // 부품발주
  "/buyer/partorder": [
    {
      poNo: 1,
      buyerComp: "구매처 A",
      partName: "부품 A",
      poQty: 50,
      poPrice: 3000,
      poState: "입고대기",
      poDate: "2025-10-01",
      buyerAddr: "대전 유성구"
    },
  ],

  // 부품재고
  "/stock/partstocks": [
    {
      poNo: 1,
      buyerComp: "구매처 A",
      partName: "부품 A",
      stockQty: 50,             // 여기서 stockQty는 poQty에서 온다
      partPrice: 3000,
      lastInDate: "2025-10-01",
    },
  ],

  // 생산
  "/plan/planlist": [
    {
      planNo: 1,
      itemName: "완제품 A",
      planQty: 100,
      planState: "생산중",
      planStartDate: "2025-10-02",
      planEndDate: "2025-11-08",
    },
  ],

  // BOM
  "/plan/bom": [
    {
      bomId: 1,
      itemName: "완제품 A",
      partName: "부품 A",
      qtyPerItem: 2
    }
  ],

  // 생산완료리스트
  "/plan/completed": [],

  // 생산완료재고
  "/stock/item": [
    {
      itemNo: 1,
      itemName: "완제품 A",
      isQty: 37,
      itemPrice: 15000,
      totalValue: 555000,
      lastUpdate: "2025-10-03",
    },
  ],
};


// 유틸: 경로 맞춰서 배열 꺼내기
function getTable(path) {
  if (!MOCK_DB[path]) {
    console.warn("[mockBackend] no mock data for", path);
    MOCK_DB[path] = [];
  }
  return MOCK_DB[path];
}

// 공용 clone
function clone(v) {
  return structuredClone ? structuredClone(v) : JSON.parse(JSON.stringify(v));
}

// GET
export function mockGet(path = {}) {
  const table = getTable(path);
  // 방어적 복사
  return clone(table);
}

// POST = 등록
export function mockPost(path, body) {
  const table = getTable(path);
  const pk = META[path]?.key;

  if (pk) {
    if (body[pk] === undefined || body[pk] === null) {
      // auto-increment
      const maxId = table.reduce(
        (max, row) => {
          const cur = Number(row[pk] ?? 0);
          return cur > max ? cur : max;
        }, 0
      );
      body = { ...body, [pk]: maxId + 1 };
    }
  }

  table.push(body);
  return clone(body);
}

// PUT = 수정
export function mockPut(path, body) {
  const table = getTable(path);
  const pk = META[path]?.key;

  if (!pk) {
    console.warn("[mockPut] no pk for", path);
    return clone(body);
  }

  const id = body[pk];
  const idx = table.findIndex(row => row[pk] === id);

  if (idx !== -1) {
    table[idx] = { ...table[idx], ...body };
    return clone(table[idx]);
  } else {
    table.push(body);
    return clone(body);
  }
}

// PATCH (부분 업데이트) -> PUT 로직 재사용
export function mockPatch(path, partial) {
  const table = getTable(path);
  const pk = META[path]?.key;

  if (!pk) {
    console.warn("[mockPatch] no pk for", path);
    return clone(partial);
  }

  const id = partial[pk];
  const idx = table.findIndex(row => row[pk] === id);

  if (idx !== -1) {
    table[idx] = { ...table[idx], ...partial };
    return clone(table[idx]);
  } else {
    // 없으면 새로 push
    table.push(partial);
    return clone(partial);
  }
}

function splitPath(path) {
  // "/order/list/3" -> { base: "/order/list", id: "3" }
  const parts = path.split("/").filter(Boolean); // ["order","list","3"]
  if (parts.length < 2) {
    return { base: path, id: null };
  }
  const idCandidate = parts[parts.length - 1];
  const base = "/" + parts.slice(0, parts.length - 1).join("/");
  return { base, id: idCandidate };
}

export function mockDelete(path, opts = {}) {
  const { base, id } = splitPath(path);
  const table = getTable(base);
  const pk = META[base]?.key;

  if (!pk) {
    console.warn("[mockDelete] no pkField for", base);
    return { success: true };
  }

  let targetId =
    id !== null
      ? (isNaN(Number(id)) ? id : Number(id))
      : opts[pk];

  if (targetId === undefined) {
    console.warn("[mockDelete] cannot resolve id for", base, path, opts);
    return { success: false };
  }

  const idx = table.findIndex(row => row[pk] === targetId);
  if (idx !== -1) {
    table.splice(idx, 1);
  }
  return { success: true };
}

// 행 이동 (완료 처리 등)
export function moveRowBetweenLists(srcPath, destPath, pk, pkValue) {
  const srcTable = getTable(srcPath);
  const destTable = getTable(destPath);

  const idx = srcTable.findIndex(row => row[pk] === pkValue);
  if (idx === -1) return null;

  const row = srcTable[idx];
  srcTable.splice(idx, 1);
  destTable.push(row);

  return clone(row);
}

// 재고 증가 유틸
export function increasePartStock({ partName, qty }) {
  const table = getTable("/stock/partstocks");
  // 단순히 push하거나 합산해도 됨.
  table.push({
    stockNo: Date.now(),
    partName,
    stockQty: qty,
    lastInDate: new Date().toISOString().slice(0, 10),
  });
}

export function increaseItemStock({ itemName, qty }) {
  const table = getTable("/stock/item");

  // 이미 있는 품목이면 qty 누적
  const found = table.find(r => r.itemName === itemName);
  if (found) {
    found.isQty = Number(found.isQty || 0) + Number(qty || 0);
    found.lastUpdate = new Date().toISOString().slice(0, 10);
    return;
  }

  table.push({
    itemNo: Date.now(),
    itemName,
    isQty: Number(qty || 0),
    lastUpdate: new Date().toISOString().slice(0, 10),
  });
}
